def component():
    # A content-derived directory prevents two app versions overwriting a live
    # component while Streamlit deploys a source update.
    fingerprint=hashlib.sha256(HTML.encode()).hexdigest()[:12]
    directory=Path(tempfile.gettempdir())/("london-monopoly-ui-"+fingerprint)
    directory.mkdir(exist_ok=True)
    target=directory/"index.html"
    if not target.exists():
        target.write_text(HTML,encoding="utf-8")
    return components.declare_component("london_table_"+fingerprint,path=str(directory))





